        {
            flag = 1;
        }
        rec::writeBits(gocpp::recv(w), flag, 3);
        rec::flush(gocpp::recv(w));
        rec::writeBits(gocpp::recv(w), int32_t(length), 16);
        rec::writeBits(gocpp::recv(w), int32_t(~ uint16_t(length)), 16);
